// Generated by AI (UnitTest MCP)
//! Optional semantic-recall embedding index (ADR-0008).
//!
//! A *complement* to the decay graph, never a replacement (ADR-0002 stands). It
//! is **off the zero-token write path**: embeddings are produced by an explicit,
//! optional `index` pass over a local OpenAI-compatible `/v1/embeddings` server
//! (Ollama, LM Studio, …), exactly like consolidation. Recall returns
//! semantically-similar node ids to seed into graph traversal; the graph still
//! does the reasoning. The module owns its own `embeddings` table so it adds no
//! schema/migration coupling.

use mindleak_model::failure;
use rusqlite::{params, Connection};
use serde_json::{json, Value};

use crate::error::{MindLeakError, ModelFailureReason, Result};
use crate::model::NodeType;

/// A local, OpenAI-compatible embeddings client (points at Ollama by default).
#[derive(Debug, Clone)]
pub struct Embedder {
    pub base_url: String,
    pub model: String,
    pub api_key: String,
}

impl Default for Embedder {
    fn default() -> Self {
        Embedder {
            base_url: std::env::var("MINDLEAK_EMBED_URL")
                .unwrap_or_else(|_| "http://localhost:11434/v1".to_string()),
            model: std::env::var("MINDLEAK_EMBED_MODEL")
                .unwrap_or_else(|_| "nomic-embed-text".to_string()),
            api_key: std::env::var("MINDLEAK_EMBED_API_KEY").unwrap_or_default(),
        }
    }
}

impl Embedder {
    /// Embed `text` into a dense vector. Errors cleanly when no model is
    /// reachable — the feature is optional and never on the hot path. Delegates
    /// to [`embed_batch`](Self::embed_batch) so single and batched paths share
    /// one implementation.
    pub fn embed(&self, text: &str) -> Result<Vec<f32>> {
        self.embed_batch(std::slice::from_ref(&text.to_string()))?
            .into_iter()
            .next()
            .ok_or_else(|| model_error("empty embedding response"))
    }

    /// Embed many texts in a **single** request. The OpenAI-compatible
    /// `/v1/embeddings` endpoint accepts an array `input` and returns `data[]`
    /// (each carrying its `index`), so the offline `index` pass costs one round
    /// trip per batch instead of one per node. Vectors are returned in input
    /// order. Errors cleanly when no model is reachable — the error is
    /// *actionable*: it names the model, the URL, and the exact remediation so a
    /// missing embedding model can never be a silent 404 (ADR-0008).
    pub fn embed_batch(&self, texts: &[String]) -> Result<Vec<Vec<f32>>> {
        if texts.is_empty() {
            return Ok(Vec::new());
        }
        let url = format!("{}/embeddings", self.base_url.trim_end_matches('/'));
        let body = json!({ "model": self.model, "input": texts });
        let value = crate::net::post_json(
            &crate::net::HttpConfig::for_model(),
            &url,
            &self.api_key,
            &body,
        )
        .map_err(|error| match error {
            MindLeakError::Model(mut failure) => {
                failure.detail = format!(
                    "semantic recall is unavailable: embedding model '{model}' could not be reached \
                     at {url} ({cause}). recall/index are optional (ADR-0008) and require a local \
                     OpenAI-compatible embeddings server. If you use Ollama, run \
                     `ollama pull {model}`; otherwise set MINDLEAK_EMBED_MODEL / MINDLEAK_EMBED_URL \
                     to a reachable model, or ignore this if you are not using semantic recall.",
                    model = self.model,
                    cause = failure.detail,
                );
                MindLeakError::Model(failure)
            }
            other => other,
        })?;
        parse_embedding_response(&value, texts.len())
    }
}

fn parse_embedding_response(value: &Value, expected_count: usize) -> Result<Vec<Vec<f32>>> {
    let data = value
        .get("data")
        .and_then(|d| d.as_array())
        .ok_or_else(|| model_error("embeddings response missing data[]"))?;
    if data.len() != expected_count {
        return Err(model_error(format!(
            "embeddings returned {} vectors for {expected_count} inputs",
            data.len()
        )));
    }
    let mut out: Vec<Vec<f32>> = vec![Vec::new(); expected_count];
    let mut dimension = None;
    for (position, item) in data.iter().enumerate() {
        let index = item
            .get("index")
            .and_then(|i| i.as_u64())
            .map(|i| i as usize)
            .unwrap_or(position);
        if index >= out.len() {
            return Err(model_error("embeddings response index out of range"));
        }
        let vector = parse_embedding_vector(item)?;
        if vector.is_empty() {
            return Err(model_error("empty embedding vector"));
        }
        match dimension {
            Some(expected) if vector.len() != expected => {
                return Err(model_error(format!(
                    "embeddings response has inconsistent dimensions: expected {expected}, got {}",
                    vector.len()
                )));
            }
            None => dimension = Some(vector.len()),
            Some(_) => {}
        }
        out[index] = vector;
    }
    if out.iter().any(Vec::is_empty) {
        return Err(model_error("embeddings response was missing a vector"));
    }
    Ok(out)
}

fn parse_embedding_vector(item: &serde_json::Value) -> Result<Vec<f32>> {
    item.get("embedding")
        .and_then(|embedding| embedding.as_array())
        .ok_or_else(|| model_error("embeddings response item missing embedding"))?
        .iter()
        .enumerate()
        .map(|(position, value)| {
            let number = value.as_f64().ok_or_else(|| {
                model_error(format!("embedding component {position} is not numeric"))
            })?;
            let narrowed = number as f32;
            if !number.is_finite() || !narrowed.is_finite() {
                return Err(model_error(format!(
                    "embedding component {position} is not finite as f32"
                )));
            }
            Ok(narrowed)
        })
        .collect()
}

fn model_error(detail: impl ToString) -> MindLeakError {
    failure(ModelFailureReason::BadJson, true, detail).into()
}

/// The embedding backend behind semantic recall (ADR-0008). A trait so the
/// index→recall→seed path can be exercised with a deterministic or unreachable
/// embedder in tests, never depending on a live model. The concrete
/// [`Embedder`] talks to a local `/v1/embeddings` server; callers inject an
/// alternative via `MindLeak::with_embedder`.
///
/// `Send + Sync` is required because `MindLeak` owns a boxed `TextEmbedder` and
/// the async maintenance worker moves the whole `MindLeak` into a background
/// thread (see the `Send` assertion in `lib.rs`).
pub trait TextEmbedder: Send + Sync {
    /// The model tag under which vectors are stored and queried.
    fn model(&self) -> &str;
    /// Embed `text` into a dense vector, erroring cleanly when unavailable.
    fn embed(&self, text: &str) -> Result<Vec<f32>>;
    /// Embed many texts, returning vectors in input order. The default fans out
    /// to [`embed`](Self::embed) so simple/test embedders work unchanged; the
    /// network [`Embedder`] overrides it to embed a whole batch in one request.
    fn embed_batch(&self, texts: &[String]) -> Result<Vec<Vec<f32>>> {
        texts.iter().map(|text| self.embed(text)).collect()
    }
}

impl TextEmbedder for Embedder {
    fn model(&self) -> &str {
        &self.model
    }
    fn embed(&self, text: &str) -> Result<Vec<f32>> {
        Embedder::embed(self, text)
    }
    fn embed_batch(&self, texts: &[String]) -> Result<Vec<Vec<f32>>> {
        Embedder::embed_batch(self, texts)
    }
}

/// Cosine similarity of two equal-length vectors; 0.0 for degenerate input.
pub fn cosine(a: &[f32], b: &[f32]) -> f32 {
    if a.is_empty() || a.len() != b.len() {
        return 0.0;
    }
    let mut dot = 0.0f32;
    let mut norm_a = 0.0f32;
    let mut norm_b = 0.0f32;
    for i in 0..a.len() {
        dot += a[i] * b[i];
        norm_a += a[i] * a[i];
        norm_b += b[i] * b[i];
    }
    let denom = norm_a.sqrt() * norm_b.sqrt();
    if denom == 0.0 {
        0.0
    } else {
        dot / denom
    }
}

fn to_blob(vector: &[f32]) -> Vec<u8> {
    vector.iter().flat_map(|f| f.to_le_bytes()).collect()
}

fn from_blob(bytes: &[u8]) -> Vec<f32> {
    bytes
        .chunks_exact(4)
        .map(|c| f32::from_le_bytes([c[0], c[1], c[2], c[3]]))
        .collect()
}

/// Create the embeddings table if it does not exist (idempotent, self-owned).
pub fn ensure_table(conn: &Connection) -> Result<()> {
    conn.execute_batch(
        "CREATE TABLE IF NOT EXISTS embeddings (
             node_id    TEXT NOT NULL,
             model      TEXT NOT NULL,
             dim        INTEGER NOT NULL,
             vector     BLOB NOT NULL,
             updated_at INTEGER NOT NULL,
             PRIMARY KEY (node_id, model)
         );",
    )?;
    Ok(())
}

/// Insert or replace the embedding for `node_id` under `model`.
pub fn upsert(
    conn: &Connection,
    node_id: &str,
    model: &str,
    vector: &[f32],
    now: i64,
) -> Result<()> {
    ensure_table(conn)?;
    conn.execute(
        "INSERT INTO embeddings (node_id, model, dim, vector, updated_at)
         VALUES (?1, ?2, ?3, ?4, ?5)
         ON CONFLICT(node_id, model) DO UPDATE SET
             dim = excluded.dim,
             vector = excluded.vector,
             updated_at = excluded.updated_at",
        params![node_id, model, vector.len() as i64, to_blob(vector), now],
    )?;
    Ok(())
}

/// Candidates a field needs before its *shape* means anything.
///
/// Below this, "stands out from the field" is not a question the data can
/// answer, so the floor alone decides and recall behaves exactly as it did
/// before. A fresh or tiny index must not be silenced by statistics it is too
/// small to support.
const DISTINCTIVE_MIN_FIELD: usize = 8;

/// How far above the field, in standard deviations, a candidate must stand to
/// count as an answer rather than as background.
///
/// Cosine similarity is **not comparable across queries**: embedding spaces are
/// anisotropic, so every text carries a baseline resemblance to every other
/// text. Measured 2026-07-27 against this repository's own index, the nonsense
/// query `zzzzqqq wibble flarp` scored **0.54** — above the 0.5 default floor —
/// because the entire field scores about that for any query at all. So an
/// absolute constant cannot tell an answer from the background, and raising it
/// is measurably worse, not better: recorded conclusions scored 0.553–0.790
/// while structural nodes matched on shared vocabulary scored 0.527–0.667, and
/// those ranges overlap. Every threshold high enough to exclude the worst
/// stranger also excludes real conclusions.
///
/// What *does* separate them is distinctiveness. A real hit stands out from its
/// own query's field; nonsense lifts the whole field uniformly and leaves
/// nothing standing above it. That is a per-query question, and this is the
/// margin it must clear.
const DISTINCTIVE_SIGMA: f32 = 1.0;

/// The ranking prior the graph already holds for a node of this kind.
///
/// The governing goal is explicit that *"embeddings may only seed graph
/// traversal"*. Ranking purely by cosine is the vector-only memory this engine
/// exists to replace: it throws away everything the graph knows and asks the
/// embedding model to be the whole answer. A recorded conclusion or decision is
/// categorically more likely to answer "what did we learn here" than a symbol
/// name or a shell command that happens to share a word with the question.
///
/// This is deliberately a **tie-breaker, not an override**. The spread is small
/// enough that a genuinely closer symbol still outranks a barely-related
/// intent, so "which function parses imports" keeps working; it only decides
/// the near-ties, which is exactly where the measured overlap lives.
fn kind_prior(kind: Option<NodeType>) -> f32 {
    match kind {
        // A conclusion, decision, or commit rationale: what a question is for.
        Some(NodeType::Intent) => 1.00,
        Some(NodeType::Artifact) => 0.92,
        Some(NodeType::Symbol) => 0.85,
        Some(NodeType::Execution) => 0.85,
        Some(NodeType::Package) => 0.80,
        // Attribution, not knowledge; it answers no question a caller asks.
        Some(NodeType::Agent) => 0.70,
        // Embedded but no longer in the graph: rank it as ordinary structure.
        None => 0.85,
    }
}

/// The score a candidate must reach to stand out from `field`.
///
/// Returns [`f32::MIN`] when the field is too small to have a shape, so the
/// floor alone decides. Returns [`f32::MAX`] when the field has no spread at
/// all: if every candidate resembles the query equally then none of them is an
/// answer, which is precisely the shape a nonsense question produces. See
/// [`DISTINCTIVE_SIGMA`] for why a per-query cut succeeds where an absolute
/// constant cannot.
fn distinctive_cut(field: &[f32]) -> f32 {
    if field.len() < DISTINCTIVE_MIN_FIELD {
        return f32::MIN;
    }
    let count = field.len() as f32;
    let mean = field.iter().sum::<f32>() / count;
    let variance = field
        .iter()
        .map(|score| (score - mean).powi(2))
        .sum::<f32>()
        / count;
    let spread = variance.sqrt();
    if spread <= f32::EPSILON {
        return f32::MAX;
    }
    mean + DISTINCTIVE_SIGMA * spread
}

/// Rank stored nodes for `model` against `query`, best first, keeping only what
/// clears `floor` *and* stands out from the field.
///
/// Two things decide an answer here, and neither is cosine alone:
///
/// 1. **It must stand out.** An absolute floor cannot separate a hit from the
///    background because cosine is not comparable across queries — see
///    [`DISTINCTIVE_SIGMA`] for the measurement. A nonsense question lifts the
///    whole field, so nothing clears its own field's cut and recall correctly
///    answers nothing.
/// 2. **The graph ranks it, not the embedding model.** Scores are ordered by
///    cosine weighted with [`kind_prior`], because the governing goal requires
///    embeddings to *seed* graph traversal rather than replace it.
///
/// The reported score stays the raw cosine, so a caller still sees the
/// similarity that was measured rather than an internal composite.
///
/// The floor keeps its original job (ADR-0053): saying nothing at all is a
/// usable answer. Without it recall always answered, and asking this
/// repository's own index for "canonical-push auto-merge armed refuses"
/// returned `merge_import`, matched on the word "merge", with nothing to signal
/// it was noise. A caller handed a plausible stranger cannot tell it is wrong,
/// and stops asking. Fall back to `multi_hop_query`, `graph_snapshot`, or the
/// repository itself.
pub fn recall(
    conn: &Connection,
    query: &[f32],
    model: &str,
    limit: usize,
    floor: f32,
) -> Result<Vec<(String, f32)>> {
    ensure_table(conn)?;
    // LEFT JOIN: an embedding may outlive the node it described, and a caller
    // asking a question is not the right moment to discover that.
    let mut stmt = conn.prepare(
        "SELECT e.node_id, e.vector, n.type
           FROM embeddings e
           LEFT JOIN nodes n ON n.id = e.node_id
          WHERE e.model = ?1",
    )?;
    let rows = stmt.query_map(params![model], |row| {
        Ok((
            row.get::<_, String>(0)?,
            row.get::<_, Vec<u8>>(1)?,
            row.get::<_, Option<String>>(2)?,
        ))
    })?;

    let mut candidates = Vec::new();
    for row in rows {
        let (id, blob, kind) = row?;
        let similarity = cosine(query, &from_blob(&blob));
        let kind = kind.as_deref().and_then(NodeType::from_tag);
        candidates.push((id, similarity, similarity * kind_prior(kind)));
    }

    let field: Vec<f32> = candidates
        .iter()
        .map(|(_, similarity, _)| *similarity)
        .collect();
    let cut = distinctive_cut(&field);

    let mut scored: Vec<(String, f32, f32)> = candidates
        .into_iter()
        .filter(|(_, similarity, _)| *similarity >= floor && *similarity >= cut)
        .collect();
    scored.sort_by(|a, b| b.2.partial_cmp(&a.2).unwrap_or(std::cmp::Ordering::Equal));
    scored.truncate(limit);
    Ok(scored
        .into_iter()
        .map(|(id, similarity, _)| (id, similarity))
        .collect())
}

/// Nodes that have no embedding for `model` yet, with the text to embed
/// (`label` + `content`). Used by the offline `index` pass.
pub fn nodes_missing_embeddings(
    conn: &Connection,
    model: &str,
    limit: usize,
) -> Result<Vec<(String, String)>> {
    ensure_table(conn)?;
    let mut stmt = conn.prepare(
        "SELECT id, label, content FROM nodes
         WHERE id NOT IN (SELECT node_id FROM embeddings WHERE model = ?1)
         LIMIT ?2",
    )?;
    let rows = stmt.query_map(params![model, limit as i64], |row| {
        let id: String = row.get(0)?;
        let label: String = row.get(1)?;
        let content: Option<String> = row.get(2)?;
        let text = match content {
            Some(c) => format!("{label}\n{c}"),
            None => label,
        };
        Ok((id, text))
    })?;
    let mut out = Vec::new();
    for row in rows {
        out.push(row?);
    }
    Ok(out)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::db;

    #[test]
    fn cosine_identical_orthogonal_and_degenerate() {
        assert!((cosine(&[1.0, 0.0], &[1.0, 0.0]) - 1.0).abs() < 1e-6);
        assert!(cosine(&[1.0, 0.0], &[0.0, 1.0]).abs() < 1e-6);
        assert_eq!(cosine(&[1.0, 0.0], &[1.0]), 0.0); // length mismatch
    }

    // A `TextEmbedder` that only implements the single-text `embed` still gets a
    // working `embed_batch` via the default fan-out, preserving input order — so
    // the batched `index` pass works with any embedder, live or stubbed.
    #[test]
    fn default_embed_batch_fans_out_in_input_order() {
        use std::sync::atomic::{AtomicUsize, Ordering};

        struct Counting {
            calls: AtomicUsize,
        }
        impl TextEmbedder for Counting {
            fn model(&self) -> &str {
                "stub"
            }
            fn embed(&self, text: &str) -> Result<Vec<f32>> {
                self.calls.fetch_add(1, Ordering::SeqCst);
                Ok(vec![text.len() as f32])
            }
        }

        let embedder = Counting {
            calls: AtomicUsize::new(0),
        };
        let out = embedder
            .embed_batch(&["a".to_string(), "bb".to_string(), "ccc".to_string()])
            .unwrap();
        assert_eq!(out, vec![vec![1.0], vec![2.0], vec![3.0]]);
        assert_eq!(embedder.calls.load(Ordering::SeqCst), 3);
    }

    #[test]
    fn unreachable_embedding_model_keeps_its_reason_and_remediation() {
        let embedder = Embedder {
            base_url: "http://127.0.0.1:1/v1".to_string(),
            model: "missing".to_string(),
            api_key: String::new(),
        };

        let error = embedder.embed("text").unwrap_err();
        let failure = error.model_failure().unwrap();

        assert_eq!(failure.reason, ModelFailureReason::Unreachable);
        assert!(failure.detail.contains("ollama pull missing"));
    }

    #[test]
    fn recall_ranks_by_cosine_similarity() {
        let conn = db::open_in_memory().unwrap();
        upsert(&conn, "artifact:a", "m", &[1.0, 0.0, 0.0], 1).unwrap();
        upsert(&conn, "artifact:b", "m", &[0.0, 1.0, 0.0], 1).unwrap();
        upsert(&conn, "artifact:c", "m", &[0.9, 0.1, 0.0], 1).unwrap();
        let hits = recall(&conn, &[1.0, 0.0, 0.0], "m", 2, 0.0).unwrap();
        assert_eq!(hits[0].0, "artifact:a");
        assert_eq!(hits[1].0, "artifact:c"); // closer than b
    }

    /// ADR-0053. Without a floor, recall always answers: this repository's own
    /// index returned `merge_import` for "canonical-push auto-merge armed
    /// refuses", matched on the word "merge". The caller cannot tell a stranger
    /// from a hit, so it learns to stop asking.
    #[test]
    fn recall_returns_nothing_when_nothing_clears_the_floor() {
        let conn = db::open_in_memory().unwrap();
        upsert(&conn, "artifact:unrelated", "m", &[0.0, 1.0], 1).unwrap();

        let hits = recall(&conn, &[1.0, 0.0], "m", 5, 0.5).unwrap();

        assert!(hits.is_empty(), "an orthogonal neighbour is not an answer");
    }

    #[test]
    fn recall_keeps_only_what_clears_the_floor() {
        let conn = db::open_in_memory().unwrap();
        upsert(&conn, "artifact:near", "m", &[1.0, 0.05], 1).unwrap();
        upsert(&conn, "artifact:far", "m", &[0.2, 1.0], 1).unwrap();

        let hits = recall(&conn, &[1.0, 0.0], "m", 5, 0.9).unwrap();

        assert_eq!(hits.len(), 1);
        assert_eq!(hits[0].0, "artifact:near");
    }

    /// Put a node in the graph so recall can read the kind the graph knows.
    fn add_node(conn: &Connection, id: &str, kind: NodeType) {
        conn.execute(
            "INSERT INTO nodes (id, type, label, content, created_at, last_accessed_at)
             VALUES (?1, ?2, ?3, NULL, 1, 1)",
            params![id, kind.as_str(), id],
        )
        .unwrap();
    }

    /// The bug this whole change exists for. Ranking by cosine alone is the
    /// vector-only memory the governing goal forbids: it discards everything
    /// the graph knows and lets the embedding model decide by itself. Measured
    /// on this repository's index, a recorded conclusion and an unrelated
    /// `merge_import` symbol landed 0.651 against 0.626 — a 0.025 gap no
    /// constant can separate. The graph can: one is a conclusion, the other is
    /// a function name that shares a word.
    #[test]
    fn a_recorded_conclusion_outranks_a_structural_node_that_scores_higher() {
        let conn = db::open_in_memory().unwrap();
        // The symbol is the closer vector, and still must not win.
        upsert(
            &conn,
            "symbol:src/merge.rs:merge_import",
            "m",
            &[1.0, 0.10],
            1,
        )
        .unwrap();
        upsert(&conn, "intent:what-we-learned", "m", &[1.0, 0.45], 1).unwrap();
        add_node(&conn, "symbol:src/merge.rs:merge_import", NodeType::Symbol);
        add_node(&conn, "intent:what-we-learned", NodeType::Intent);

        let hits = recall(&conn, &[1.0, 0.0], "m", 5, 0.0).unwrap();

        assert_eq!(
            hits[0].0, "intent:what-we-learned",
            "the conclusion is the answer even though the symbol is nearer"
        );
        assert!(
            hits[0].1 < hits[1].1,
            "and the reported score stays the honest cosine, not the ranking composite"
        );
    }

    /// Nonsense must be answerable with silence. Cosine is not comparable
    /// across queries, so `zzzzqqq wibble flarp` scored 0.54 against this
    /// repository's index — above the 0.5 floor — because the whole field
    /// scores about that for anything. A uniform field means nothing stands
    /// out, and nothing standing out is the honest answer.
    #[test]
    fn recall_answers_nothing_when_no_candidate_stands_out_from_the_field() {
        let conn = db::open_in_memory().unwrap();
        for n in 0..12 {
            // A field that all resembles the query about equally.
            upsert(&conn, &format!("artifact:{n}"), "m", &[1.0, 0.60], 1).unwrap();
        }

        let hits = recall(&conn, &[1.0, 0.0], "m", 5, 0.5).unwrap();

        assert!(
            hits.is_empty(),
            "every candidate cleared the floor, and not one of them was an answer"
        );
    }

    /// The same field, plus one genuine outlier: recall must still answer, and
    /// answer with only the node that stands out.
    #[test]
    fn recall_returns_the_candidate_that_stands_out_from_an_otherwise_flat_field() {
        let conn = db::open_in_memory().unwrap();
        for n in 0..12 {
            upsert(&conn, &format!("artifact:{n}"), "m", &[1.0, 0.60], 1).unwrap();
        }
        upsert(&conn, "artifact:answer", "m", &[1.0, 0.0], 1).unwrap();

        let hits = recall(&conn, &[1.0, 0.0], "m", 5, 0.5).unwrap();

        assert_eq!(hits.len(), 1, "only the outlier is an answer");
        assert_eq!(hits[0].0, "artifact:answer");
    }

    /// A small or fresh index has no distribution to reason about, so the floor
    /// alone must keep deciding. Statistics must not silence an index that is
    /// merely young.
    #[test]
    fn a_field_too_small_to_have_a_shape_is_judged_by_the_floor_alone() {
        let conn = db::open_in_memory().unwrap();
        for n in 0..3 {
            upsert(&conn, &format!("artifact:{n}"), "m", &[1.0, 0.60], 1).unwrap();
        }

        let hits = recall(&conn, &[1.0, 0.0], "m", 5, 0.5).unwrap();

        assert_eq!(
            hits.len(),
            3,
            "three lookalikes are too few to call any of them background"
        );
    }

    #[test]
    fn upsert_replaces_vector_for_same_node_and_model() {
        let conn = db::open_in_memory().unwrap();
        upsert(&conn, "n", "m", &[1.0, 0.0], 1).unwrap();
        upsert(&conn, "n", "m", &[0.0, 1.0], 2).unwrap();
        let hits = recall(&conn, &[0.0, 1.0], "m", 5, 0.0).unwrap();
        assert_eq!(hits.len(), 1);
        assert!((hits[0].1 - 1.0).abs() < 1e-6);
    }

    /// Regression: a missing/unreachable embedding model must produce an
    /// *actionable* error (naming the model, `ollama pull`, and the env
    /// overrides), never a bare mysterious HTTP status. Uses an unreachable URL
    /// so no live model is required.
    #[test]
    fn embed_error_is_actionable_when_model_unreachable() {
        let embedder = Embedder {
            base_url: "http://127.0.0.1:1/v1".to_string(),
            model: "nomic-embed-text".to_string(),
            api_key: String::new(),
        };
        let message = embedder.embed("hello").unwrap_err().to_string();
        assert!(
            message.contains("nomic-embed-text"),
            "error must name the model: {message}"
        );
        assert!(
            message.contains("ollama pull"),
            "error must name the remediation: {message}"
        );
        assert!(
            message.contains("MINDLEAK_EMBED_MODEL"),
            "error must name the config override: {message}"
        );
    }

    /// Regression: a mixed-type vector used to drop the bad component, report
    /// success, and persist a shorter vector that semantic recall could not match.
    #[test]
    fn embed_batch_rejects_non_numeric_components() {
        let response = json!({
            "data": [{"index": 0, "embedding": [0.1, "bad", 0.2]}]
        });
        let error = parse_embedding_response(&response, 1).unwrap_err();

        assert!(error.to_string().contains("not numeric"));
    }

    /// Regression: a finite JSON number can overflow when narrowed to `f32`;
    /// storing infinity poisons cosine ranking just as surely as malformed JSON.
    #[test]
    fn embed_batch_rejects_components_that_are_not_finite_f32() {
        let response = json!({
            "data": [{"index": 0, "embedding": [3.5e38, 0.2]}]
        });
        let error = parse_embedding_response(&response, 1).unwrap_err();

        assert!(error.to_string().contains("not finite"));
    }

    /// Regression: one malformed item could establish a different dimension
    /// from its peers, leaving only part of the batch recallable without warning.
    #[test]
    fn embed_batch_rejects_inconsistent_dimensions() {
        let response = json!({
            "data": [
                {"index": 0, "embedding": [0.1, 0.2]},
                {"index": 1, "embedding": [0.1, 0.2, 0.3]}
            ]
        });
        let error = parse_embedding_response(&response, 2).unwrap_err();

        assert!(error.to_string().contains("inconsistent dimensions"));
    }

    /// Live round-trip against a running embedding model (e.g.
    /// `ollama pull nomic-embed-text`). Ignored by default; run with
    /// `cargo test -p mindleak-core -- --ignored`.
    #[test]
    #[ignore = "requires a running local embedding model (e.g. nomic-embed-text)"]
    fn live_embed_round_trip() {
        let vector = Embedder::default()
            .embed("session token validation and jwt expiry")
            .expect("live embedding should return a vector");
        assert!(!vector.is_empty());
        eprintln!("live embed -> {} dims", vector.len());
    }
}
